n=a3.pA(a9,"\u05db\u05dc \u05d4\u05d6\u05db\u05d5\u05d9\u05d5\u05ea \u05d1\u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d4, \u05dc\u05e8\u05d1\u05d5\u05ea \u05e7\u05d5\u05d3 \u05d4\u05de\u05e7\u05d5\u05e8, \u05d4\u05e2\u05d9\u05e6\u05d5\u05d1, \u05d4\u05dc\u05d5\u05d2\u05d5, \u05d4\u05de\u05de\u05e9\u05e7, \u05d4\u05ea\u05db\u05e0\u05d9\u05dd \u05d5\u05d4\u05ea\u05d9\u05e2\u05d5\u05d3, \u05e9\u05de\u05d5\u05e8\u05d5\u05ea \u05dc\u05de\u05e4\u05e2\u05d9\u05dc. \u05d0\u05d9\u05df \u05dc\u05d4\u05e2\u05ea\u05d9\u05e7, \u05dc\u05e9\u05db\u05e4\u05dc, \u05dc\u05d4\u05e4\u05d9\u05e5, \u05dc\u05e4\u05e8\u05e1\u05dd, \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05d5 \u05dc\u05d9\u05e6\u05d5\u05e8 \u05d9\u05e6\u05d9\u05e8\u05d5\u05ea \u05e0\u05d2\u05d6\u05e8\u05d5\u05ea \u05de\u05d4\u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d4 \u05dc\u05dc\u05d0 \u05d0\u05d9\u05e9\u05d5\u05e8 \u05de\u05e8\u05d0\u05e9 \u05d5\u05d1\u05db\u05ea\u05d1.","6. \u05e7\u05e0\u05d9\u05d9\u05df \u05e8\u05d5\u05d7\u05e0\u05d9")
m=a3.pA(a9,"\u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d4 \u05db\u05e4\u05d5\u05e3 \u05d2\u05dd \u05dc\u05de\u05d3\u05d9\u05e0\u05d9\u05d5\u05ea \u05d4\u05e4\u05e8\u05d8\u05d9\u05d5\u05ea \u05e9\u05dc\u05e0\u05d5, \u05d4\u05de\u05d4\u05d5\u05d5\u05d4 \u05d7\u05dc\u05e7 \u05d1\u05dc\u05ea\u05d9 \u05e0\u05e4\u05e8\u05d3 \u05de\u05ea\u05e0\u05d0\u05d9\u05dd \u05d0\u05dc\u05d4. \u05d0\u05e0\u05d0 \u05e7\u05e8\u05d0 \u05d0\u05ea \u05de\u05d3\u05d9\u05e0\u05d9\u05d5\u05ea \u05d4\u05e4\u05e8\u05d8\u05d9\u05d5\u05ea \u05d1\u05e2\u05d9\u05d5\u05df \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05e4\u05dc\u05d9\u05e7\u05e6\u05d9\u05d4.","7. \u05e4\u05e8\u05d8\u05d9\u05d5\u05ea")
l=a3.pA(a9,"\u05d0\u05e0\u05d5 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05ea \u05de\u05d9\u05e8\u05d1 \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05dc\u05d4\u05d1\u05d8\u05d9\u05d7 \u05e9\u05d4\u05e9\u05d9\u05e8\u05d5\u05ea \u05d9\u05d4\u05d9\u05d4 \u05d6\u05de\u05d9\u05df \u05d1\u05d0\u05d5\u05e4\u05df \u05e8\u05e6\u05d9\u05e3, \u05d0\u05da \u05d0\u05d9\u05e0\u05e0\u05d5 \u05de\u05ea\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05d6\u05de\u05d9\u05e0\u05d5\u05ea \u05d1\u05dc\u05ea\u05d9 \u05e4\u05d5\u05e1\u05e7\u05ea. \u05d4\u05e9\u05d9\u05e8\u05d5\u05ea \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d5\u05e9\u05d1\u05ea \u05de\u05e2\u05ea \u05dc\u05e2\u05ea \u05dc\u05e6\u05d5\u05e8\u05da \u05ea\u05d7\u05d6\u05d5\u05e7\u05d4, \u05e9\u05d3\u05e8\u05d5\u05d2\u05d9\u05dd \u05d0\u05d5 \u05de\u05e1\u05d9\u05d1\u05d5\u05ea \u05d8\u05db\u05e0\u05d9\u05d5\u05ea, \u05dc\u05dc\u05d0 \u05d4\u05d5\u05d3\u05e2\u05d4 \u05de\u05d5\u05e7\u05d3\u05de\u05ea.\n\n\u05d0\u05d9\u05e0\u05e0\u05d5 \u05d0\u05d7\u05e8\u05d0\u05d9\u05dd \u05dc\u05db\u05dc \u05e0\u05d6\u05e7 \u05e9\u05d9\u05d9\u05d2\u05e8\u05dd \u05e2\u05e7\u05d1 \u05d7\u05d5\u05e1\u05e8 \u05d6\u05de\u05d9\u05e0\u05d5\u05ea \u05e9\u05dc \u05d4\u05e9\u05d9\u05e8\u05d5\u05ea.","8. \u05d6\u05de\u05d9\u05e0\u05d5\u05ea \u05d4\u05e9\u05d9\u05e8\u05d5\u05ea")
